import React from "react";
import {
  FiHome,
  FiFileText,
  FiUsers,
  FiTarget,
  FiBell
} from "react-icons/fi";

// Main Dashboard Components
import DirectorDashboard from "views/direktur/dashboard/DirectorDashboard";

// Reports & Analytics Components
import ExecutiveReports from "views/direktur/reports/ExecutiveReports";

// Institutional Overview Components
import InstitutionalOverview from "views/direktur/institutional/InstitutionalOverview";


// Decision Support Components
import DecisionSupport from "views/direktur/decision/DecisionSupport";

// Notifications (shared)
import NotificationsPage from "views/shared/notifications/NotificationsPage";

const routes = [
  // ============================================
  // EXECUTIVE DASHBOARD (dengan semua indikator dan analitik terintegrasi)
  // ============================================
  {
    name: "Dashboard Eksekutif",
    layout: "/pimpinan",
    path: "dashboard",
    icon: <FiHome className="h-6 w-6" />,
    component: <DirectorDashboard />,
  },
  
  // ============================================
  // EXECUTIVE REPORT GENERATION (semua laporan dalam satu menu)
  // ============================================
  {
    name: "Laporan Eksekutif",
    layout: "/pimpinan",
    path: "reports",
    icon: <FiFileText className="h-6 w-6" />,
    component: <ExecutiveReports />,
  },
  
  // ============================================
  // INSTITUTIONAL OVERVIEW (semua overview dalam satu menu)
  // ============================================
  {
    name: "Ikhtisar Institusi",
    layout: "/pimpinan",
    path: "institutional",
    icon: <FiUsers className="h-6 w-6" />,
    component: <InstitutionalOverview />,
  },
  
  
  // ============================================
  // DECISION SUPPORT (dukungan pengambilan keputusan)
  // ============================================
  {
    name: "Dukungan Keputusan",
    layout: "/pimpinan",
    path: "decision",
    icon: <FiTarget className="h-6 w-6" />,
    component: <DecisionSupport />,
  },
  // ============================================
  // NOTIFICATIONS
  // ============================================
  {
    name: "Notifikasi",
    layout: "/pimpinan",
    path: "notifications",
    icon: <FiBell className="h-6 w-6" />,
    component: <NotificationsPage />,
  },
];

export default routes;