import React from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { Provider } from "react-redux"; // Import Provider dari react-redux
import { store } from './store/index.js';
import PpmppLayout from "layouts/ppmpp";
import KoordinatorLayout from "layouts/koordinator";
import PimpinanLayout from "layouts/pimpinan";
import AuthLayout from "layouts/auth";

const App = () => {
  return (
    // Bungkus aplikasi dengan Provider dan berikan store Redux
    <Provider store={store}>
      <div className="relative">
        <Routes>
          <Route path="auth/*" element={<AuthLayout />} />
          <Route path="ppmpp/*" element={<PpmppLayout />} />
          <Route path="koordinator/*" element={<KoordinatorLayout />} />
          <Route path="pimpinan/*" element={<PimpinanLayout />} />
          <Route path="/" element={<Navigate to="/auth/homepage" replace />} />
        </Routes>
      </div>
    </Provider>
  );
};

export default App;

